func BenchmarkArtDmxMarshalBinary(b *testing.B) {
	data := artnet.ArtDmx{
		Sequence: 237,
		Physical: 0,
		SubUni:   1,
		Net:      0,
		Data:     make([]uint8, 512),
	}

	for b.Loop() {
		_, err := data.MarshalBinary()
		if err != nil {
			b.Fatalf("failed to encode ArtDmx: %s", err)
		}
	}
}

